Think: Validate each file in temp_workspace by reading filenames from file_list.txt, checking each file has exactly four space-separated tokens and that the last three are numeric; record valid filenames and log malformed ones.

Act: bash

```bash
awk '{
 fn="temp_workspace/"$0
 if((getline content < fn) <= 0){ print $0 " : cannot read or empty" >> "temp_workspace/errors.log"; close(fn); next }
 close(fn)
 gsub(/^[ \t]+|[ \t]+$/,"",content)
 n=split(content,a,/[\t ]+/)
 if(n!=4){ print $0 " : wrong token count (" n ")" >> "temp_workspace/errors.log"; next }
 num_re="^[0-9]+(\\.[0-9]+)?$"
 if(!(a[2] ~ num_re && a[3] ~ num_re && a[4] ~ num_re)){ print $0 " : non-numeric score(s)" >> "temp_workspace/errors.log"; next }
 print $0 >> "temp_workspace/valid_files.txt"
}' temp_workspace/file_list.txt
```

