Think: Extract the fractional component from the canonical numeric interpretation in int_check_workspace/var_numeric.txt and save it to int_check_workspace/var_fraction.txt (handle non-numeric errors too).

Act: bash

```bash
awk '{
 s=$0; gsub(/^[ \t\r\n]+|[ \t\r\n]+$/,"",s);
 if(s ~ /^ERROR:/){ print s > "int_check_workspace/var_fraction.txt"; exit }
 num = s + 0;
 frac = num - int(num);
 if(frac < 0) frac = -frac;
 if(frac < 1e-12) frac = 0;
 printf "%.15g\n", frac > "int_check_workspace/var_fraction.txt"
}' int_check_workspace/var_numeric.txt
